PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS rubric_versions(version TEXT PRIMARY KEY, sha256 TEXT NOT NULL, json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS packs(pack_id TEXT PRIMARY KEY, manifest_sha256 TEXT NOT NULL, pack_json_sha256 TEXT NOT NULL, rubric_version TEXT NOT NULL REFERENCES rubric_versions(version), created_at TEXT NOT NULL, pack_path TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs(run_id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('pack','bench','judge')), renderer_commit TEXT, renderer_dirty INTEGER, tracker_sha256 TEXT, page_sha256 TEXT, tuning_json TEXT, benchmark_sha256 TEXT, started_at TEXT NOT NULL, notes TEXT);
CREATE TABLE IF NOT EXISTS images(image_id TEXT PRIMARY KEY, file_sha256 TEXT NOT NULL, lapa_stem TEXT NOT NULL, face_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('render','sticker','real')), shade TEXT, hex TEXT, finish TEXT, mouth TEXT, ita REAL, ita_bin TEXT, monk TEXT, yaw REAL, split TEXT NOT NULL CHECK(split IN ('pool','test')), repeat_of TEXT, benchmark_id TEXT, renderer_commit TEXT, renderer_dirty INTEGER, tracker_sha256 TEXT, page_sha256 TEXT, tuning_json TEXT, intensity REAL, render_script_sha256 TEXT, pack_id TEXT NOT NULL REFERENCES packs(pack_id), created_at TEXT NOT NULL, source TEXT NOT NULL, source_split TEXT NOT NULL, source_image_sha256 TEXT NOT NULL, label_sha256 TEXT NOT NULL, full_path TEXT NOT NULL, crop_path TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS human_ratings(rater_id TEXT NOT NULL, image_id TEXT NOT NULL REFERENCES images(image_id), rubric_version TEXT NOT NULL REFERENCES rubric_versions(version), checks_json TEXT NOT NULL, overall INTEGER NOT NULL CHECK(overall BETWEEN 1 AND 5), seconds REAL NOT NULL, note TEXT, source_csv_sha256 TEXT NOT NULL, imported_at TEXT NOT NULL, order_index INTEGER, UNIQUE(rater_id,image_id,rubric_version));
CREATE TABLE IF NOT EXISTS rating_imports(source_csv_sha256 TEXT PRIMARY KEY, rater_id TEXT NOT NULL, pack_id TEXT NOT NULL REFERENCES packs(pack_id), source_path TEXT NOT NULL, imported_at TEXT NOT NULL, rows_imported INTEGER NOT NULL, source_mtime_ns INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS code_metrics(image_id TEXT NOT NULL REFERENCES images(image_id), metric TEXT NOT NULL, value REAL, metric_version TEXT NOT NULL, run_id TEXT NOT NULL REFERENCES runs(run_id), UNIQUE(image_id,metric,metric_version,run_id));
CREATE TABLE IF NOT EXISTS judge_scores(run_id TEXT NOT NULL REFERENCES runs(run_id), image_id TEXT NOT NULL REFERENCES images(image_id), method TEXT NOT NULL CHECK(method IN ('zero_shot','rag','knn_mean')), repeat_index INTEGER NOT NULL, model_id TEXT, revision TEXT, k INTEGER, checks_json TEXT, overall REAL, total REAL, reason TEXT, latency_s REAL, valid INTEGER NOT NULL, questions_json TEXT, metadata_json TEXT, UNIQUE(run_id,image_id,method,repeat_index));
